div.script:
document.getElementById('launch-btn').onclick = async function() {
  try {
    const rawUrl = "https://raw.githubusercontent.com/Mistyitz/EduForgePlatform-/main/index.html";
    const response = await fetch(rawUrl);

    if (!response.ok) throw new Error("Could not load index.html");
    const htmlCode = await response.text();

    const win = window.open('about:blank', '_blank');
    if (win) {
      win.document.open();

      const securityOverlay = `
        <div id="security-modal" style="position:fixed; top:0; left:0; width:100vw; height:100vh; background:#0f172a; z-index:999999; display:flex; flex-direction:column; justify-content:center; align-items:center; font-family:-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color:#ffffff; text-align:center;">
          <div style="background:#1e293b; border:1px solid #334155; padding:32px; border-radius:12px; max-width:400px; width:85%;">
            <h2 style="margin-top:0; font-size:1.5rem; color:#f8fafc;">Enter Secure Mode</h2>
            <p style="color:#94a3b8; font-size:0.95rem; line-height:1.5;">EduWorld requires Fullscreen and Focus enforcement to run. Closing full screen or switching tabs will end your session.</p>
            <div style="display:flex; gap:12px; margin-top:24px;">
              <button id="cancel-sec-btn" style="flex:1; padding:10px; border:1px solid #475569; background:transparent; color:#f8fafc; border-radius:6px; font-weight:600; cursor:pointer;">Cancel</button>
              <button id="start-sec-btn" style="flex:1; padding:10px; border:none; background:#2563eb; color:#ffffff; border-radius:6px; font-weight:600; cursor:pointer;">Proceed</button>
            </div>
          </div>
        </div>

        <script>
          document.getElementById('cancel-sec-btn').onclick = function() {
            window.close();
          };

          document.getElementById('start-sec-btn').onclick = async function() {
            try {
              // Request full screen directly attached to this user click gesture
              if (document.documentElement.requestFullscreen) {
                await document.documentElement.requestFullscreen();
              } else if (document.documentElement.webkitRequestFullscreen) {
                await document.documentElement.webkitRequestFullscreen();
              }
            } catch (e) {
              console.log("Fullscreen request was rejected.");
            }

            // Lock system hotkeys where supported
            if (navigator.keyboard && navigator.keyboard.lock) {
              try {
                await navigator.keyboard.lock(['Escape', 'Tab', 'AltLeft', 'AltRight']);
              } catch (e) {
                console.log("Keyboard lock not permitted.");
              }
            }

            // Hide the overlay modal
            document.getElementById('security-modal').style.display = 'none';

            // Enforce lock rules
            document.addEventListener('fullscreenchange', () => {
              if (!document.fullscreenElement) {
                window.close();
              }
            });

            document.addEventListener('visibilitychange', () => {
              if (document.hidden) {
                window.close();
              }
            });

            window.addEventListener('blur', () => {
              window.close();
            });
          };
        <\/script>
      `;

      win.document.write(securityOverlay + htmlCode);
      win.document.close();
    } else {
      alert("Popup blocked! Please allow popups to launch EduWorld.");
    }
  } catch (err) {
    alert("Failed to fetch application code from GitHub.");
  }
};
